                            _fxr = _ps_acct["factions"]
                            for _fac, _cur_f, _tot_f in (
                                    ("kurzick", 1, 2), ("luxon", 3, 4),
                                    ("imperial", 5, 6), ("balthazar", 11, 12)):
                                if _fac in _fxr:
                                    player_attrs[_cur_f] = \
                                        _fxr[_fac]["current"]
